begin;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.failure(statement text) returns text language plpgsql as $$begin execute statement;return 'OK';exception when others then return case when sqlstate='P0001' then sqlerrm else sqlstate end;end$$;
select ok(private.payment_text_has_reference('Matched abc-12 against the statement.',encode(extensions.digest('abc-12','sha256'),'hex')),'Embedded reference detected');
select ok(private.payment_text_has_reference('Matched two words.',encode(extensions.digest('two words','sha256'),'hex')),'Multiword reference detected');
select ok(private.payment_text_has_reference(U&'Checked cafe\0301.',encode(extensions.digest(U&'caf\00e9','sha256'),'hex')),'NFC reference detected');
select ok(not private.payment_text_has_reference('Matched ABC-12.',encode(extensions.digest('abc-12','sha256'),'hex')),'Case remains significant');
select ok(not has_table_privilege('service_role','public.admin_audit_log','TRUNCATE'),'Service cannot truncate immutable audits');
insert into auth.users(id,email) values('00000000-0000-0000-0000-000000000901','privacy-admin@example.invalid'),('00000000-0000-0000-0000-000000000902','privacy-candidate@example.invalid');
insert into public.admin_users(user_id) values('00000000-0000-0000-0000-000000000901');
insert into public.payment_offers(id,code,name,amount_minor,accepted_methods,instructions) values('00000000-0000-0000-0000-000000000903','synthetic','Synthetic',100,array['easypaisa']::public.payment_method[],'Synthetic');
insert into public.payment_submissions(id,user_id,offer_id,offer_code,currency,amount_minor,access_days,payment_method,transaction_id_ciphertext,transaction_id_hash,transaction_id_masked)
values('00000000-0000-0000-0000-000000000904','00000000-0000-0000-0000-000000000902','00000000-0000-0000-0000-000000000903','synthetic','PKR',100,30,'easypaisa',decode('01'||repeat('00',29),'hex'),encode(extensions.digest('abc-12','sha256'),'hex'),'********c-12');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(pg_temp.failure($$select public.qiyadat_payment_decide('00000000-0000-0000-0000-000000000901','00000000-0000-0000-0000-000000000904','approve','{"verification_note":"Matched abc-12."}','00000000-0000-0000-0000-000000000905')$$),'VALIDATION_ERROR','Full reference cannot enter a note');
select is(pg_temp.failure($$select public.qiyadat_payment_decide('00000000-0000-0000-0000-000000000901','00000000-0000-0000-0000-000000000904','reject','{"reason_code":"OTHER","message":"Please check abc-12."}','00000000-0000-0000-0000-000000000905')$$),'VALIDATION_ERROR','Full reference cannot enter rejection text');
select is((select status::text from public.payment_submissions where id='00000000-0000-0000-0000-000000000904'),'pending','Rejected private text rolls back payment');
select is((select count(*)::integer from public.entitlements),0,'Rejected private text rolls back entitlement');
select is((select count(*)::integer from public.admin_audit_log),0,'Rejected private text leaves no audit');
reset role;
create function pg_temp.audit_failure() returns trigger language plpgsql as $$begin raise exception using errcode='P0001',message='SYNTHETIC_AUDIT_FAILURE';end$$;
create trigger synthetic_audit_failure before insert on public.admin_audit_log for each row execute function pg_temp.audit_failure();
set local role service_role;
select is(pg_temp.failure($$select public.qiyadat_payment_decide('00000000-0000-0000-0000-000000000901','00000000-0000-0000-0000-000000000904','approve','{"verification_note":"Matched synthetic statement."}','00000000-0000-0000-0000-000000000905')$$),'SYNTHETIC_AUDIT_FAILURE','Audit failure aborts decision transaction');
select is((select status::text from public.payment_submissions where id='00000000-0000-0000-0000-000000000904'),'pending','Audit failure rolls back payment');
select is((select count(*)::integer from public.entitlements),0,'Audit failure rolls back entitlement');
reset role;
drop trigger synthetic_audit_failure on public.admin_audit_log;
select * from finish();
rollback;
